services:
  api:
    build: ./src/Api
    ports: ["8080:8080"]
    environment:
      ConnectionStrings__Db: "Host=db;Database=app;Username=app;Password=${DB_PASSWORD}"
      ConnectionStrings__Redis: "redis:6379"
    depends_on:
      db: { condition: service_healthy }
      redis: { condition: service_started }
  db:
    image: postgres:17
    environment: { POSTGRES_USER: app, POSTGRES_PASSWORD: "${DB_PASSWORD}", POSTGRES_DB: app }
    healthcheck: { test: ["CMD-SHELL", "pg_isready -U app -d app"], interval: 5s, retries: 10 }
  redis: { image: "redis:7-alpine" }

envFrom:
  - configMapRef: { name: api-config }
env:
  - name: ConnectionStrings__Db
    valueFrom:
      secretKeyRef: { name: api-secrets, key: db-connection }

resources:
  requests: { cpu: "250m", memory: "512Mi" }
  limits:   { memory: "512Mi" }

apiVersion: autoscaling/v2
kind: HorizontalPodAutoscaler
metadata: { name: api }
spec:
  scaleTargetRef: { apiVersion: apps/v1, kind: Deployment, name: api }
  minReplicas: 2
  maxReplicas: 10
  metrics:
    - type: Resource
      resource: { name: cpu, target: { type: Utilization, averageUtilization: 70 } }

deploy-prod:
  needs: deploy-staging
  runs-on: ubuntu-latest
  environment: production          # wymaga zatwierdzenia
  permissions: { id-token: write, contents: read }
  steps:
    - uses: azure/login@v2
      with:
        client-id: ${{ vars.AZURE_CLIENT_ID }}
        tenant-id: ${{ vars.AZURE_TENANT_ID }}
        subscription-id: ${{ vars.AZURE_SUBSCRIPTION_ID }}
    - run: az containerapp update -n api -g rg-prod --image myacr.azurecr.io/api:${{ github.sha }}

